/* ============================================================
   assets.js — imagens embutidas (base64)
   ------------------------------------------------------------
   Por que base64 e não arquivos .png soltos?
   O html2canvas (que gera o PNG para download) só consegue
   "fotografar" imagens se elas não forem bloqueadas pelo
   navegador. Abrindo o projeto com duplo clique (file://),
   imagens de arquivo são tratadas como outra origem e ficam
   de fora do PNG exportado. Em base64 isso nunca acontece.

   Uso no HTML:  <img data-asset="logo">
   (o shared.js preenche o src automaticamente)
   ============================================================ */
window.ASSETS = {
  logo: "data:image/png;base64,",
  whatsapp: "data:image/png;base64,",
  email: "data:image/png;base64,"
};
